sitNFT; NFT public fundingNFT; MPHMinter public mphMinter; event EDeposit( address indexed sender, uint256 indexed depositID, uint256 amount, uint256 maturationTimestamp, uint256 interestAmount, uint256 mintMPHAmount ); event EWithdraw( address indexed sender, uint256 indexed depositID, uint256 indexed fundingID, bool early, uint256 takeBackMPHAmount ); event EFund( address indexed sender, uint256 indexed fundingID, uint256 deficitAmount ); event ESetParamAddress( address indexed sender, string indexed paramName, address newValue ); event ESetParamUint( address indexed sender, string indexed paramName, uint256 newValue ); struct DepositLimit { uint256 MinDepositPeriod; uint256 MaxDepositPeriod; uint256 MinDepositAmount; uint256 MaxDepositAmount; uint256 DepositFee; } constructor( DepositLimit memory _depositLimit, address _moneyMarket, address _stablecoin, address _feeModel, address _interestModel, address _interestOracle, address _depositNFT, address _fundingNFT, address _mphMinter ) public { require( _moneyMarket.isContract() && _stablecoin.isContract() && _feeModel.isContract() && _interestModel.isContract() && _interestOracle.isContract() && _depositNFT.isContract() && _fundingNFT.isContract() && _mphMinter.isContract(), "DInterest: An input address is not a contract" ); moneyMarket = IMoneyMarket(_moneyMarket); stablecoin = ERC20(_stablecoin); feeModel = IFeeModel(_feeModel); interestModel = IInterestModel(_interestModel); interestOracle = IInterestOracle(_interestOracle); depositNFT = NFT(_depositNFT); fundingNFT = NFT(_fundingNFT); mphMinter = MPHMinter(_mphMinter); require( moneyMarket.stablecoin() == _stablecoin, "DInterest: moneyMarket.stablecoin() != _stablecoin" ); require( interestOracle.moneyMarket() == _moneyMarket, "DInterest: interestOracle.moneyMarket() != _moneyMarket" ); require( _depositLimit.MaxDepositPeriod > 0 && _depositLimit.MaxDepositAmount > 0, "DInterest: An input uint256 is 0" ); require( _depositLimit.MinDepositPeriod <= _depositLimit.MaxDepositPeriod, "DInterest: Invalid DepositPeriod range" ); require( _depositLimit.MinDepositAmount <= _depositLimit.MaxDepositAmount, "DInterest: Invalid DepositAmount range" ); MinDepositPeriod = _depositLimit.MinDepositPeriod; MaxDepositPeriod = _depositLimit.MaxDepositPeriod; MinDepositAmount = _depositLimit.MinDepositAmount; MaxDepositAmount = _depositLimit.MaxDepositAmount; DepositFee = _depositLimit.DepositFee; totalDeposit = 0; } function deposit(uint256 amount, uint256 maturationTimestamp) external nonReentrant { _deposit(amount, maturationTimestamp); } function withdraw(uint256 depositID, uint256 fundingID) external nonReentrant { _withdraw(depositID, fundingID, false); } function earlyWithdraw(uint256 depositID, uint256 fundingID) external nonReentrant { _withdraw(depositID, fundingID, true); } function multiDeposit( uint256[] calldata amountList, uint256[] calldata maturationTimestampList ) external nonReentrant { require( amountList.length == maturationTimestampList.length, "DInterest: List lengths unequal" ); for (uint256 i = 0; i < amountList.length; i = i.add(1)) { _deposit(amountList[i], maturationTimestampList[i]); } } function multiWithdraw( uint256[] calldata depositIDList, uint256[] calldata fundingIDList ) external nonReentrant { require( depositIDList.length == fundingIDList.length, "DInterest: List lengths unequal" ); for (uint256 i = 0; i < depositIDList.length; i = i.add(1)) { _withdraw(depositIDList[i], fundingIDList[i], false); } } function multiEarlyWithdraw( uint256[] calldata depositIDList, uint256[] calldata fundingIDList ) external nonReentrant { require( depositIDList.length == fundingIDList.length, "DInterest: List lengths unequal" ); for (uint256 i = 0; i < depositIDList.length; i = i.add(1)) { _withdraw(depositIDList[i], fundingIDList[i], true); } } function fundAll() external nonReentrant { (bool isNegative, uint256 deficit) = surplus(); require(isNegative, "DInterest: No deficit available"); require( !depositIsFunded(deposits.length), "DInterest: All deposits funded" ); uint256 incomeIndex = moneyMarket.incomeIndex(); require(incomeIndex > 0, "DInterest: incomeIndex == 0"); fundingList.push( Funding({ fromDepositID: latestFundedDepositID, toDepositID: deposits.length, recordedFundedDepositAmount: unfundedUserDepositAmount, recordedMoneyMarketIncomeIndex: incomeIndex, creationTimestamp: now }) ); sumOfRecordedFundedDepositAndInterestAmountDivRecordedIncomeIndex = sumOfRecordedFundedDepositAndInterestAmountDivRecordedIncomeIndex .add( unfundedUserDepositAmount.mul(EXTRA_PRECISION).div(incomeIndex) ); latestFundedDepositID = deposits.length; unfundedUserDepositAmount = 0; _fund(deficit); } function fundMultiple(uint256 toDepositID) external nonReentrant { require( toDepositID > latestFundedDepositID, "DInterest: Deposits already funded" ); require( toDepositID <= deposits.length, "DInterest: Invalid toDepositID" ); (bool isNegative, uint256 surplus) = surplus(); require(isNegative, "DInterest: No deficit available"); uint256 totalDeficit = 0; uint256 totalSurplus = 0; uint256 totalDepositAndInterestToFund = 0; for ( uint256 id = latestFundedDepositID.add(1); id <= toDepositID; id = id.add(1) ) { Deposit storage depositEntry = _getDeposit(id); if (depositEntry.active) { (isNegative, surplus) = surplusOfDeposit(id); } else { (isNegative, surplus) = ( depositEntry.finalSurplusIsNegative, depositEntry.finalSurplusAmount ); } if (isNegative) { totalDeficit = totalDeficit.add(surplus); } else { totalSurplus = totalSurplus.add(surplus); } if (depositEntry.active) { totalDepositAndInterestToFund = totalDepositAndInterestToFund .add(depositEntry.amount) .add(depositEntry.interestOwed); } } if (totalSurplus >= totalDeficit) { revert("DInterest: Selected deposits in surplus"); } else { totalDeficit = totalDeficit.sub(totalSurplus); } uint256 incomeIndex = moneyMarket.incomeIndex(); require(incomeIndex > 0, "DInterest: incomeIndex == 0"); fundingList.push( Funding({ fromDepositID: latestFundedDepositID, toDepositID: toDepositID, recordedFundedDepositAmount: totalDepositAndInterestToFund, recordedMoneyMarketIncomeIndex: incomeIndex, creationTimestamp: now }) ); sumOfRecordedFundedDepositAndInterestAmountDivRecordedIncomeIndex = sumOfRecordedFundedDepositAndInterestAmountDivRecordedIncomeIndex .add( totalDepositAndInterestToFund.mul(EXTRA_PRECISION).div(incomeIndex) ); latestFundedDepositID = toDepositID; unfundedUserDepositAmount = unfundedUserDepositAmount.sub( totalDepositAndInterestToFund ); _fund(totalDeficit); } function payInterestToFunder(uint256 fundingID) external returns (uint256 interestAmount) { address funder = fundingNFT.ownerOf(fundingID); require(funder == msg.sender, "DInterest: not funder"); Funding storage f = _getFunding(fundingID); uint256 currentMoneyMarketIncomeIndex = moneyMarket.incomeIndex(); interestAmount = f .recordedFundedDepositAmount .mul(currentMoneyMarketIncomeIndex) .div(f.recordedMoneyMarketIncomeIndex) .sub(f.recordedFundedDepositAmount); sumOfRecordedFundedDepositAndInterestAmountDivRecordedIncomeIndex = sumOfRecordedFundedDepositAndInterestAmountDivRecordedIncomeIndex .sub( f.recordedFundedDepositAmount.mul(EXTRA_PRECISION).div( f.recordedMoneyMarketIncomeIndex ) ); f.recordedMoneyMarketIncomeIndex = currentMoneyMarketIncomeIndex; sumOfRecordedFundedDepositAndInterestAmountDivRecordedIncomeIndex = sumOfRecordedFundedDepositAndInterestAmountDivRecordedIncomeIndex .add( f.recordedFundedDepositAmount.mul(EXTRA_PRECISION).div( f.recordedMoneyMarketIncomeIndex ) ); if (interestAmount > 0) { interestAmount = moneyMarket.withdraw(interestAmount); if (interestAmount > 0) { stablecoin.safeTransfer(funder, interestAmount); } } } function calculateInterestAmount( uint256 depositAmount, uint256 depositPeriodInSeconds ) public returns (uint256 interestAmount) { (, uint256 moneyMarketInterestRatePerSecond) = interestOracle.updateAndQuery(); (bool surplusIsNegative, uint256 surplusAmount) = surplus(); return interestModel.calculateInterestAmount( depositAmount, depositPeriodInSeconds, moneyMarketInterestRatePerSecond, surplusIsNegative, surplusAmount ); } function totalInterestOwedToFunders() public returns (uint256 interestOwed) { uint256 currentValue = moneyMarket .incomeIndex() .mul( sumOfRecordedFundedDepositAndInterestAmountDivRecordedIncomeIndex ) .div(EXTRA_PRECISION); uint256 initialValue = totalDeposit.add(totalInterestOwed).sub(unfundedUserDepositAmount); if (currentValue < initialValue) { return 0; } return currentValue.sub(initialValue); } function surplus() public returns (bool isNegative, uint256 surplusAmount) { uint256 totalValue = moneyMarket.totalValue(); uint256 totalOwed = totalDeposit.add(totalInterestOwed).add( totalInterestOwedToFunders() ); if (totalValue >= totalOwed) { isNegative = false; surplusAmount = totalValue.sub(totalOwed); } else { isNegative = true; surplusAmount = totalOwed.sub(totalValue); } } function surplusOfDeposit(uint256 depositID) public returns (bool isNegative, uint256 surplusAmount) { Deposit storage depositEntry = _getDeposit(depositID); uint256 currentMoneyMarketIncomeIndex = moneyMarket.incomeIndex(); uint256 currentDepositValue = depositEntry.amount.mul(currentMoneyMarketIncomeIndex).div( depositEntry.initialMoneyMarketIncomeIndex ); uint256 owed = depositEntry.amount.add(depositEntry.interestOwed); if (currentDepositValue >= owed) { isNegative = false; surplusAmount = currentDepositValue.sub(owed); } else { isNegative = true; surplusAmount = owed.sub(currentDepositValue); } } function depositIsFunded(uint256 id) public view returns (bool) { return (id <= latestFundedDepositID); } function depositsLength() external view returns (uint256) { return deposits.length; } function fundingListLength() external view returns (uint256) { return fundingList.length; } function getDeposit(uint256 depositID) external view returns (Deposit memory) { return deposits[depositID.sub(1)]; } function getFunding(uint256 fundingID) external view returns (Funding memory) { r